    string buffer;
    size_t pos;
    vector<string> tokens;

    void readLine() {
        if (getline(in, buffer)) {
            tokens.clear();
            pos = 0;
            istringstream iss(buffer);
            string token;
            while (iss >> token) {
                tokens.push_back(token);
            }
        } else {
            tokens.clear();
            pos = 0;
        }
    }

public:
    Parser(istream& input) : in(input), pos(0) {
        readLine();
    }

    string next() {
        if (pos >= tokens.size()) {
            readLine();
        }
        if (pos < tokens.size()) {
            return tokens[pos++];
        }
        return "";
    }

    int nextInt() {
        return stoi(next());
    }

    long long nextLong() {
        return stoll(next());
    }
};

