        vector<vector<long long>> ret(n+1, vector<long long>(n+1, 0));

        for (int i = 0; i <= n; i++) {
            ret[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                ret[i][j] = (ret[i-1][j-1] + ret[i-1][j]) % mod;
            }
        }

        return ret;
    }
};

class Matrix {
public:
