    vector<vector<long long>> a;

    Matrix(int size) : n(size), a(size, vector<long long>(size, 0)) {}

    static Matrix identity(int size) {
        Matrix ret(size);
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                ret.a[i][j] = 0;
            }
            ret.a[i][i] = 1;
        }
        return ret;
    }

    Matrix multiply(const Matrix& b, long long mod) const {
        Matrix resp(n);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                resp.a[i][j] = 0;
                for (int k = 0; k < n; k++) {
                    resp.a[i][j] = (resp.a[i][j] + a[i][k] * b.a[k][j]) % mod;
